def groups_bg(grid):
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    active=[i for i,row in enumerate(grid) if any(v!=bg for v in row)]
    gr=[]
    for i in active:
        if not gr or i!=gr[-1][-1]+1: gr.append([i])
        else: gr[-1].append(i)
    return bg,gr

def shift_scores(g):
    bg,gs=groups_bg(g); H=len(gs[0]); W=len(g[0])
    A=np.array(g)[gs[0]]!=bg; B=np.array(g)[gs[1]]!=bg
    vals=[]
    for s in range(-5,6):
        # B column c equals A column c-s (mapping source A to target B with offset s)
        lo=max(0,s); hi=min(W,W+s)
        # report matches only over the shorter pattern width from left, roughly max among prefix columns where both bboxes active
        # full overlap score and exact prefix length
        mismatch=(A[:,lo-s:hi-s]!=B[:,lo:hi]).sum()
        prefix=0
        for c in range(W):
            ca=c-s
            if ca<0 or ca>=W: break
            if np.array_equal(A[:,ca],B[:,c]): prefix+=1
            else: break
        vals.append((s,int(mismatch),prefix))
    return sorted(vals,key=lambda z:(-z[2],z[1]))
